<template><el-table v-loading="loading" :data="items" class="admin-data-table" stripe><el-table-column prop="name" label="角色名称" min-width="180"><template #default="{row}"><strong>{{ row.name }}</strong></template></el-table-column><el-table-column label="权限数量" width="120" align="center"><template #default="{row}">{{ row.permissions.length }}</template></el-table-column><el-table-column prop="admin_count" label="管理员" width="110" align="center"/><el-table-column label="状态" width="110"><template #default="{row}"><StatusBadge :label="row.status===1?'启用':'停用'" :type="row.status===1?'success':'gray'"/></template></el-table-column><el-table-column prop="updated_at" label="更新时间" width="170"/><el-table-column label="操作" width="150" fixed="right" align="center"><template #default="{row}"><el-button link type="primary" :icon="Edit" @click="emit('edit',row)">编辑</el-button><el-button link type="danger" :icon="Delete" :disabled="row.admin_count>0" @click="emit('delete',row)">删除</el-button></template></el-table-column></el-table></template>
<script setup lang="ts">import { Delete,Edit } from '@element-plus/icons-vue';import StatusBadge from '@/components/admin/StatusBadge.vue';import type{RoleItem}from'../types';defineProps<{items:RoleItem[];loading:boolean}>();const emit=defineEmits<{(e:'edit',row:RoleItem):void;(e:'delete',row:RoleItem):void}>();</script>
